namespace VinsPDF {
internal sealed partial class MainForm {
    TextStyle inlineAppliedStyle;bool inlineLoading;
    float InlineDpi {get{using(var g=inlineText.CreateGraphics())return g.DpiY;}}
    Font InlineRunFont(TextStyle s){return new Font(s.Family,Math.Max(1,s.Size*(float)canvas.Scale),Flags(s),GraphicsUnit.Pixel);}
    static FontStyle Flags(TextStyle s){return(s.Bold?FontStyle.Bold:0)|(s.Italic?FontStyle.Italic:0)|(s.Underline?FontStyle.Underline:0)|(s.Strike?FontStyle.Strikeout:0);}
    void InitialiseInlineRuns(){inlineLoading=true;inlineText.Text=inlineOriginal;var runs=inlineObject==null?new List<TextRun>():TextRuns030.For(inlineObject);int position=0;foreach(var run in runs){if(position>=inlineText.TextLength)break;inlineText.Select(position,Math.Min(run.Text.Length,inlineText.TextLength-position));using(var f=InlineRunFont(run.Style)){inlineText.SelectionFont=f;}inlineText.SelectionColor=run.Style.Ink??Color.Black;position+=run.Text.Length;}inlineText.SelectAll();inlineText.SelectionAlignment=textStyle.Alignment==1?HorizontalAlignment.Center:textStyle.Alignment==2?HorizontalAlignment.Right:HorizontalAlignment.Left;inlineAppliedStyle=textStyle.Copy();inlineLoading=false;}
