        for(int i=from;i<to;i++){inlineText.Select(i,1);using(var current=inlineText.SelectionFont??(Font)inlineText.Font.Clone()){FontStyle flags=current.Style;if(old.Bold!=textStyle.Bold)flags=textStyle.Bold?flags|FontStyle.Bold:flags&~FontStyle.Bold;if(old.Italic!=textStyle.Italic)flags=textStyle.Italic?flags|FontStyle.Italic:flags&~FontStyle.Italic;if(old.Underline!=textStyle.Underline)flags=textStyle.Underline?flags|FontStyle.Underline:flags&~FontStyle.Underline;if(old.Strike!=textStyle.Strike)flags=textStyle.Strike?flags|FontStyle.Strikeout:flags&~FontStyle.Strikeout;string family=old.Family!=textStyle.Family?textStyle.Family:current.FontFamily.Name;float pixels=Math.Abs(old.Size-textStyle.Size)>.001f?textStyle.Size*(float)canvas.Scale:current.SizeInPoints*InlineDpi/72;using(var f=new Font(family,Math.Max(1,pixels),flags,GraphicsUnit.Pixel))inlineText.SelectionFont=f;}if(old.Ink!=textStyle.Ink)inlineText.SelectionColor=textStyle.Ink??Color.Black;}
        if(old.Alignment!=textStyle.Alignment){inlineText.Select(from,to-from);inlineText.SelectionAlignment=textStyle.Alignment==1?HorizontalAlignment.Center:textStyle.Alignment==2?HorizontalAlignment.Right:HorizontalAlignment.Left;}inlineText.Select(start,length);inlineAppliedStyle=textStyle.Copy();inlineLoading=false;LayoutInline();}
    List<TextRun> CaptureInlineRuns(){var result=new List<TextRun>();int start=inlineText.SelectionStart,length=inlineText.SelectionLength;inlineLoading=true;for(int i=0;i<inlineText.TextLength;i++){inlineText.Select(i,1);var style=textStyle.Copy();using(var f=inlineText.SelectionFont??(Font)inlineText.Font.Clone()){style.Family=f.FontFamily.Name;style.Size=f.SizeInPoints*InlineDpi/72/(float)canvas.Scale;style.Bold=f.Bold;style.Italic=f.Italic;style.Underline=f.Underline;style.Strike=f.Strikeout;}style.Ink=inlineText.SelectionColor;string text=inlineText.Text.Substring(i,1);if(result.Count>0&&SameRunStyle(result[result.Count-1].Style,style))result[result.Count-1].Text+=text;else result.Add(new TextRun{Text=text,Style=style});}inlineText.Select(start,length);inlineLoading=false;return result;}
    internal static bool SameRunStyle(TextStyle a,TextStyle b){return a.Family==b.Family&&Math.Abs(a.Size-b.Size)<.05f&&Flags(a)==Flags(b)&&a.Ink==b.Ink;}
}
internal sealed partial class PdfEngine {
    sealed class RichLine {public readonly List<TextRun> Runs=new List<TextRun>();public float Width,Height;}
    public int PutRichTextBlock(int index,int[] oldIds,List<TextRun> runs,TextStyle style,PointF position,float angle=0){if(runs.Count==0)throw new InvalidOperationException("Enter text.");if(runs.All(r=>MainForm.SameRunStyle(r.Style,runs[0].Style))){var uniform=runs[0].Style.Copy();uniform.Wrap=style.Wrap;uniform.BoxWidth=style.BoxWidth;uniform.Alignment=style.Alignment;uniform.LineHeight=style.LineHeight;uniform.ParagraphGap=style.ParagraphGap;uniform.BlockKey=style.BlockKey;return PutTextBlock(index,oldIds,string.Concat(runs.Select(r=>r.Text)),uniform,position,angle);}
        EnsureEditableGroups();string block=style.BlockKey??"VinsPDF.Block."+Guid.NewGuid().ToString("N");var lines=new List<RichLine>();var line=new RichLine();using(var bitmap=new Bitmap(1,1))using(var g=Graphics.FromImage(bitmap))using(var format=(StringFormat)StringFormat.GenericTypographic.Clone()){format.FormatFlags|=StringFormatFlags.MeasureTrailingSpaces;foreach(var run in runs)foreach(string part in Regex.Split(run.Text.Replace("\r\n","\n"),@"(\n|[^\S\n]+)")){if(part.Length==0)continue;if(part=="\n"){lines.Add(line);line=new RichLine();continue;}float width;using(var font=new Font(run.Style.Family,run.Style.Size,(run.Style.Bold?FontStyle.Bold:0)|(run.Style.Italic?FontStyle.Italic:0),GraphicsUnit.Pixel))width=g.MeasureString(part,font,int.MaxValue,format).Width+Math.Max(0,part.Length-1)*run.Style.CharacterSpacing;if(style.Wrap&&style.BoxWidth>0&&line.Width+width>style.BoxWidth&&line.Runs.Count>0&&!string.IsNullOrWhiteSpace(part)){lines.Add(line);line=new RichLine();}line.Runs.Add(new TextRun{Text=part,Style=run.Style});line.Width+=width;line.Height=Math.Max(line.Height,run.Style.Size); }lines.Add(line);
        int first=-1;float down=0;double radians=angle*Math.PI/180,cos=Math.Cos(radians),sin=Math.Sin(radians);Batch(index,delegate{foreach(var row in lines){float advance=style.Alignment==1?Math.Max(0,style.BoxWidth-row.Width)/2:style.Alignment==2?Math.Max(0,style.BoxWidth-row.Width):0;foreach(var run in row.Runs){var fragment=run.Style.Copy();fragment.Wrap=false;fragment.Alignment=0;fragment.BoxWidth=0;fragment.BlockKey=block;if(!string.IsNullOrWhiteSpace(run.Text)){PointF point=new PointF(position.X+(float)(advance*cos-down*sin)/Sizes[index].Width,position.Y+(float)(advance*sin+down*cos)/Sizes[index].Height);int id=PutTextBlock(index,new int[0],run.Text,fragment,point,angle);if(first<0)first=id;}using(var font=new Font(fragment.Family,fragment.Size,(fragment.Bold?FontStyle.Bold:0)|(fragment.Italic?FontStyle.Italic:0),GraphicsUnit.Pixel))advance+=g.MeasureString(run.Text,font,int.MaxValue,format).Width+Math.Max(0,run.Text.Length-1)*fragment.CharacterSpacing;}down+=Math.Max(style.Size,row.Height)*style.LineHeight+(row.Runs.Count==0?style.ParagraphGap:0);}DeleteObjects(index,oldIds);});return first;}
    }
}
}
